'use client';
import { useEffect, useRef, useState } from 'react';
import { cx } from '../lib/cx';
import { useIsoLayoutEffect, useReducedMotion } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { Spin, Swap, Tip } from '../lib/motion';
import '../designme.css';
import './toast.css';

export type ToastTone = 'success' | 'error' | 'info' | 'loading';

export interface ToastData {
  /** A new id slides a new toast in and the old one away. Keep the id to change the text in place */
  id: string | number;
  /** Picks the icon and its colour (in Clean only success and error take colour). loading spins */
  tone?: ToastTone;
  title: string;
  /** The quieter line under the title. Crossfades when it changes */
  description?: string;
  /** The one action, a button on the toast's row just before the close button, like Undo or Retry: ghost (the usual), or
      primary on the accent (ink, the old name, still works). On a narrow toast, or when the words run past two lines, it
      moves to a row of its own under them, at the end. A toast with an action should stay at least 10 seconds.
      busy swaps its label for a spinner; done swaps it for the green tick and turns the button off (Undo once it has undone).
      Either way the button eases to its new width */
  action?: { label: string; onClick: () => void; variant?: 'ghost' | 'primary' | 'ink'; busy?: boolean; done?: boolean; doneLabel?: string };
}

export interface ToastProps {
  /** The toast to show, or null for none */
  toast: ToastData | null;
  /** Called by the close button. The toast leaves either way */
  onDismiss?: (id: ToastData['id']) => void;
  className?: string;
}

const TONES: Record<ToastTone, { icon: 'ok' | 'alert' | 'info' | null; color: string; bg: string }> = {
  success: { icon: 'ok', color: 'var(--dm-ok)', bg: 'var(--dm-ok-bg)' },
  error: { icon: 'alert', color: 'var(--dm-bad)', bg: 'var(--dm-bad-bg)' },
  info: { icon: 'info', color: 'var(--dm-pb)', bg: 'var(--dm-pb-bg)' },
  loading: { icon: null, color: 'var(--dm-fg)', bg: 'var(--dm-chip)' }
};

const cssMs = (el: Element, v: string) => { const s = getComputedStyle(el).getPropertyValue(v).trim(); return (s.endsWith('ms') ? parseFloat(s) : parseFloat(s) * 1000) || 340; };

function Card({ toast, leaving, onDismiss }: { toast: ToastData; leaving: boolean; onDismiss: () => void }) {
  const tone = TONES[toast.tone ?? 'success'], a = toast.action;
  // a pressed action never goes blank and keeps no room for what it turns into: it shows its new content and eases from its
  // old width to its new one
  const reduce = useReducedMotion(), btn = useRef<HTMLButtonElement>(null), w = useRef(0), tx = useRef<HTMLDivElement>(null);
  // the action sits on the toast's row, before the close button; when the words run past two lines beside it, it moves to a
  // row of its own under them (on a narrow toast, a phone, the stylesheet does that whatever the words)
  const [wrap, setWrap] = useState(false);
  useIsoLayoutEffect(() => {
    const el = tx.current; if (!el || !a) { setWrap(false); return; }
    const lines = new Set<number>(), tw = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
    for (let n = tw.nextNode(); n; n = tw.nextNode()) { const g = document.createRange(); g.selectNodeContents(n); Array.from(g.getClientRects()).forEach(b => { if (b.width > 1) lines.add(Math.round(b.top / 4)); }); }
    if (lines.size > 2) setWrap(true);
  }, [toast.id, !!a]);
  const look = a ? (a.done ? 'done' : a.busy ? 'busy' : a.label) : '';
  useIsoLayoutEffect(() => {
    const b = btn.current; if (!b) { w.current = 0; return; }
    const w1 = b.getBoundingClientRect().width, w0 = w.current; w.current = w1;
    if (w0 && !reduce && Math.abs(w1 - w0) > .5) b.animate([{ width: w0 + 'px' }, { width: w1 + 'px' }], { duration: cssMs(b, '--dm-t'), easing: getComputedStyle(b).getPropertyValue('--dm-ease').trim() || 'ease' });
  }, [look]);
  return (
    <div className={cx('dm-tst-t', leaving ? 'dm-tst-out' : 'dm-tst-in', wrap && 'dm-wrap')} role="status" inert={leaving}>
      <span className="dm-g" data-tone={toast.tone ?? 'success'} style={{ color: tone.color, background: tone.bg }}>{tone.icon ? <Icon name={tone.icon} /> : <Spin />}</span>
      <div className="dm-tx" ref={tx}><b className={toast.tone === 'loading' ? 'dm-shim' : undefined}>{toast.title}</b>{toast.description !== undefined && <Swap>{toast.description}</Swap>}</div>
      <div className="dm-acts">
        {a && <button type="button" ref={btn} className={cx('dm-pill dm-sm', a.variant === 'primary' || a.variant === 'ink' ? 'dm-primary' : 'dm-ghost', a.done && 'dm-done')} aria-busy={a.busy || undefined}
          aria-disabled={a.done || undefined} aria-label={a.done ? a.doneLabel ?? 'Done' : undefined} onClick={() => { if (!a.busy && !a.done) a.onClick(); }}>{a.done ? <Icon name="check" /> : a.busy ? <Spin /> : a.label}</button>}
        <Tip label="Dismiss"><button type="button" className="dm-ib" aria-label="Dismiss" onClick={onDismiss}><Icon name="x" /></button></Tip>
      </div>
    </div>
  );
}

/** One toast at a time: a new one rises in while the last one slips away. */
export function Toast({ toast, onDismiss, className }: ToastProps) {
  const reduce = useReducedMotion();
  // the close button hides the toast straight away, whether or not the parent clears it
  const [closed, setClosed] = useState<ToastData['id']>();
  const shown = toast && toast.id !== closed ? toast : null;
  // the toast on screen, kept so it can play its exit after the prop moves on
  const [cur, setCur] = useState(shown);
  const [leaving, setLeaving] = useState<ToastData[]>([]);
  if ((shown?.id ?? null) !== (cur?.id ?? null)) {
    if (cur) setLeaving(l => [...l, cur]);
    setCur(shown);
  } else if (shown !== cur) setCur(shown);
  useEffect(() => {
    if (!leaving.length) return;
    const t = setTimeout(() => setLeaving(l => l.slice(1)), reduce ? 0 : 300);
    return () => clearTimeout(t);
  }, [leaving, reduce]);

  return (
    <div data-dm="" className={cx('dm-tst-slot', className)} aria-live="polite">
      {leaving.filter(t => t.id !== cur?.id).map(t => <Card key={'t' + t.id} toast={t} leaving onDismiss={() => {}} />)}
      {cur && <Card key={'t' + cur.id} toast={cur} leaving={false} onDismiss={() => { setClosed(cur.id); onDismiss?.(cur.id); }} />}
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Toast ---------- */
/* the toast on its way out and the one coming in share one cell, so each keeps its full width while they cross; the cell is
   as tall as its toast and keeps no room when there is none (owner, 18 and 19 Nov) */
.dm-tst-slot{width:100%;display:grid;justify-items:center;align-items:center}
.dm-tst-slot>*{grid-area:1/1}
/* the same size as a toast in Toast stack: width, padding, type and icons */
/* 16px in all round (owner, 19 Nov). The icon, the title, the action and Close share the title's line (Close on the title's
   first line, its glyph on the content's right edge and its hover circle reaching out round it); the second line runs under
   the title. Hover fills are a quiet 5% so they show on the white toast */
.dm-tst-t{display:flex;align-items:flex-start;gap:var(--dm-s-3);padding:var(--dm-s-4);--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent);background:var(--dm-raised);border-radius:var(--dm-r-card);box-shadow:var(--dm-shadow-toast);max-width:380px;width:100%;position:relative;overflow:hidden}
.dm-tst-t .dm-g{width:28px;height:28px;margin-top:calc(8.775px - 14px);border-radius:50%;display:grid;place-items:center;flex:none}
.dm-tst-t .dm-tx{flex:1;min-width:0;font-size:13px;line-height:1.35}
.dm-tst-t .dm-tx b{font-weight:500;display:block}
.dm-tst-t .dm-tx span{font-size:12px;color:var(--dm-muted)}
.dm-tst-t .dm-acts{display:flex;align-items:center;gap:2px;margin:calc(8.775px - 14px) -6px 0 0}
/* the buttons in its row are one height in every style: the close button is as tall as the 28px pill beside it */
.dm-tst-t .dm-ib{width:28px;height:28px}
/* a pressed action never goes blank: Undo turns into the vivid green tick (a done confirmation), Retry into a spinner, each
   as wide as what it shows, easing to it */
.dm-tst-t .dm-acts .dm-pill{overflow:hidden}
.dm-tst-t .dm-acts .dm-pill.dm-done{color:var(--dm-ok-mark);pointer-events:none}
.dm-tst-t .dm-acts .dm-pill.dm-done .dm-i{width:16px;height:16px;stroke-width:2}
.dm-tst-t .dm-life{display:none}
/* the action sits on the toast's own row, just before Close (the message, the action as a ghost button, Close at the far end:
   the usual snackbar). When the toast is narrow (a phone) or its words run past two lines (.wrap, set as it shows), the action
   moves to a row of its own under the message, its words ending under Close's glyph, and Close stays at the top end
   (owner, 22 Nov) */
.dm-tst-slot{container:tst/inline-size}
.dm-tst-t.dm-wrap{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:start;row-gap:var(--dm-s-1)}
.dm-tst-t.dm-wrap .dm-acts{display:contents}
.dm-tst-t.dm-wrap .dm-ib{grid-area:1/3;margin:calc(8.775px - 14px) -6px 0 0}
.dm-tst-t.dm-wrap .dm-acts .dm-pill{grid-area:2/2/3/4;justify-self:end;margin:0 -10px -6px 0}
@container tst (max-width:340px){
  .dm-tst-t{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:start;row-gap:var(--dm-s-1)}
  .dm-tst-t .dm-acts{display:contents}
  .dm-tst-t .dm-ib{grid-area:1/3;margin:calc(8.775px - 14px) -6px 0 0}
  .dm-tst-t .dm-acts .dm-pill{grid-area:2/2/3/4;justify-self:end;margin:0 -10px -6px 0}
}
.dm-tst-in{animation:dm-tstin .6s var(--dm-ease) both}
@keyframes dm-tstin{from{opacity:0;transform:translateY(14px) scale(.97);filter:blur(5px)}to{opacity:1;transform:none;filter:none}}
.dm-tst-out{animation:dm-tstout .35s var(--dm-ease) both}
@keyframes dm-tstout{to{opacity:0;transform:translateY(8px) scale(.98);filter:blur(4px)}}
/* Clean (lead, 18 Nov): a toast is a small card, not a pill: its content 16px in from every edge and ordinary round corners
   (16px), with the hairline and the raised shadow. The status shows only on its small icon, with no disc behind it: green for
   success, red for an error; info and loading stay grey, so a toast carries two hues at most. It rises 8px from .98 and
   leaves with a fade, with no blur */
:root[data-style="clean"] .dm-tst-t,:root [data-style="clean"] .dm-tst-t,:root [data-style="clean"].dm-tst-t{gap:12px;padding:16px;border-radius:calc(12px * var(--dm-rk-l,var(--dm-rk)))}
:root[data-style="clean"] .dm-tst-t .dm-g,:root [data-style="clean"] .dm-tst-t .dm-g,:root [data-style="clean"].dm-tst-t .dm-g{width:20px;height:20px;margin-top:calc(8.775px - 10px);background:none!important;color:var(--dm-fg2)!important}
:root[data-style="clean"] .dm-tst-t .dm-g .dm-i,:root [data-style="clean"] .dm-tst-t .dm-g .dm-i,:root [data-style="clean"].dm-tst-t .dm-g .dm-i{width:20px;height:20px}
:root[data-style="clean"] .dm-tst-t .dm-g .dm-spin,:root [data-style="clean"] .dm-tst-t .dm-g .dm-spin,:root [data-style="clean"].dm-tst-t .dm-g .dm-spin{width:14px;height:14px}
:root[data-style="clean"] .dm-tst-t .dm-g[data-tone="success"],:root [data-style="clean"] .dm-tst-t .dm-g[data-tone="success"],:root [data-style="clean"].dm-tst-t .dm-g[data-tone="success"]{color:var(--dm-ok-mark)!important}
:root[data-style="clean"] .dm-tst-t .dm-g[data-tone="error"],:root [data-style="clean"] .dm-tst-t .dm-g[data-tone="error"],:root [data-style="clean"].dm-tst-t .dm-g[data-tone="error"]{color:var(--dm-bad-mark)!important}
:root[data-style="clean"] .dm-tst-t .dm-acts,:root [data-style="clean"] .dm-tst-t .dm-acts,:root [data-style="clean"].dm-tst-t .dm-acts{gap:4px}
@keyframes dm-tstoutc{to{opacity:0;transform:translateY(6px) scale(.98)}}
:root[data-style="clean"] .dm-tst-in,:root [data-style="clean"] .dm-tst-in,:root [data-style="clean"].dm-tst-in{animation:dm-clcard var(--dm-t-slow) var(--dm-ease) both}
:root[data-style="clean"] .dm-tst-out,:root [data-style="clean"] .dm-tst-out,:root [data-style="clean"].dm-tst-out{animation:dm-tstoutc var(--dm-t-fast) var(--dm-ease) both}
/* with no blur to hide them, the two never show through each other: a new toast rises once the old one has faded */
:root[data-style="clean"] .dm-tst-out~.dm-tst-in,:root [data-style="clean"] .dm-tst-out~.dm-tst-in,:root [data-style="clean"].dm-tst-out~.dm-tst-in{animation-delay:.16s}
